effect.shader:
const int N = 64;

// Buffers de 8 bits: a raiz quadrada dá precisão ao escuro (a ponta do raio).
vec4 guardar(vec4 v) { return vec4(sqrt(clamp(v.rgb, 0.0, 1.0)), clamp(v.a, 0.0, 1.0)); }
vec4 abrir(vec4 g) { return vec4(g.rgb * g.rgb, g.a); }

/** A fonte de um pixel da camada: limiar, tinta, oclusão, pré-multiplicada; alfa 1 dentro do quadro. */
vec4 fonteEm(vec2 uv) {
    vec4 c = texture(inputImg, uv);
    float t = threshold * 0.01;
    if (t > 0.0) {
        float s = thresholdSmooth * 0.01;
        if (thresholdMode == 0) {
            float g = (c.r + c.g + c.b) * 0.333;
            c.rgb *= smoothstep(t - s, t + s, g);
        } else {
            c.rgb *= smoothstep(vec3(t - s), vec3(t + s), c.rgb);
        }
    }
    vec3 luz = c.rgb * rayColor.rgb * c.a;
    // Sem camada escolhida o motor entrega 1×1 (empty="transparent").
    if (textureSize(occluderImg, 0).x > 1) luz *= 1.0 - texture(occluderImg, uv).a;
    return vec4(luz, 1.0);
}

/** A fonte (passe 0) lida em qualquer uv: espelhada além da borda, ou nada (Repeat Edges). */
vec4 fonteLida(vec2 uv) {
    if (repeatEdges) return abrir(texture(a, 1.0 - abs(mod(uv, 2.0) - 1.0)));
    if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) return vec4(0.0);
    return abrir(texture(a, uv));
}

/** O raio Zoom de um canal: densidade `d`, os sentidos pela Direction. */
vec4 zoom(vec2 uv, vec2 pos, float d, float jit) {
    vec2 passo = (uv - pos) * d / float(N);
    float queda = 1.0 - 2.0 * decay / float(N);
    vec4 soma = vec4(0.0);
    if (direction == 0 || direction == 2) {
        vec2 p = uv - passo * (1.0 - jit);
        float w = exposure / float(N);
        for (int i = 0; i < N; i++) { soma += fonteLida(p) * w; w *= queda; p -= passo; }
    }
    if (direction == 1 || direction == 2) {
        vec2 p = uv - passo * (1.0 - jit);
        if (direction == 2) p += passo;
        float w = exposure / float(N);
        for (int i = 0; i < N; i++) { soma += fonteLida(p) * w; w *= queda; p += passo; }
    }
    return soma;
}

/** O giro em volta da Position (x corrigido por altura/largura, como o Crate's). */
vec2 girar(vec2 uv, vec2 pos, float ang) {
    float asp = acResolution.y / acResolution.x;
    vec2 r = uv - pos;
    r.x /= asp;
    float c = cos(ang);
    float s = sin(ang);
    r = vec2(r.x * c + r.y * s, -r.x * s + r.y * c);
    r.x *= asp;
    return r + pos;
}

vec4 spin(vec2 uv, vec2 pos, float incr) {
    float queda = 1.0 - 0.5 * decay / float(N);
    float w = exposure / float(N);
    float ang = 0.0;
    vec4 soma = vec4(0.0);
    for (int i = 0; i < N; i++) {
        soma += (fonteLida(girar(uv, pos, ang)) + fonteLida(girar(uv, pos, -ang))) * w;
        ang += incr;
        w *= queda;
    }
    return soma;
}

vec4 oRaio() {
    vec2 uv = acScreenNorm;
    // Ruído intercalado: desloca o começo de cada pixel numa fração do passo (some na tenda).
    float jit = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
    float ca = caAmount * 0.01;
    if (mode == 1) {
        float incr = amount * 0.01 / float(N);
        if (ca == 0.0) return spin(uv, position, incr);
        vec3 k = caChannels == 0 ? vec3(1.0 + ca, 1.0, 1.0 - ca)
               : (caChannels == 1 ? vec3(1.0 + ca, 1.0 - ca, 1.0) : vec3(1.0, 1.0 + ca, 1.0 - ca));
        vec4 r = spin(uv, position, incr * k.r);
        vec4 g = spin(uv, position, incr * k.g);
        vec4 b = spin(uv, position, incr * k.b);
        return vec4(r.r, g.g, b.b, (r.a + g.a + b.a) * 0.333);
    }
    // Length em pixels da camada (o buffer está em escala de prévia: volta pela acEscalaDePixel).
    float largura = float(textureSize(inputImg, 0).x) / max(acEscalaDePixel, 1e-4);
    float d = min(rayLength / largura, 1.0);
    if (ca == 0.0) return zoom(uv, position, d, jit);
    float m = ca * 0.1;
    vec3 dd = caChannels == 0 ? vec3(d + m, d, d - m) : (caChannels == 1 ? vec3(d + m, d - m, d) : vec3(d, d + m, d - m));
    vec4 r = zoom(uv, position, dd.r, jit);
    vec4 g = zoom(uv, position, dd.g, jit);
    vec4 b = zoom(uv, position, dd.b, jit);
    return vec4(r.r, g.g, b.b, (r.a + g.a + b.a) * 0.333);
}

/** O raio pronto, lido com uma tenda de quatro leituras (sobe de 1/2 sem degrau). */
vec4 raioPronto(vec2 uv) {
    vec2 t = 0.5 / vec2(textureSize(b, 0));
    return 0.25 * (abrir(texture(b, uv + vec2(-t.x, -t.y))) + abrir(texture(b, uv + vec2(t.x, -t.y)))
        + abrir(texture(b, uv + vec2(-t.x, t.y))) + abrir(texture(b, uv + vec2(t.x, t.y))));
}

void main() {
    if (acPass == 0) {
        // Média dos 4 pixels cheios do bloco: o limiar vale por pixel, antes da média.
        vec2 px = 1.0 / vec2(textureSize(inputImg, 0));
        vec2 uv = acScreenNorm;
        vec4 f = 0.25 * (fonteEm(uv + vec2(-0.5, -0.5) * px) + fonteEm(uv + vec2(0.5, -0.5) * px)
            + fonteEm(uv + vec2(-0.5, 0.5) * px) + fonteEm(uv + vec2(0.5, 0.5) * px));
        fragColor = guardar(f);
        return;
    }
    if (acPass == 1) { fragColor = guardar(oRaio()); return; }

    vec2 uv = acScreenNorm;
    if (view == 2) {
        fragColor = vec4(clamp(fonteEm(uv).rgb, 0.0, 1.0), 1.0);
        return;
    }
    vec4 r = raioPronto(uv);
    vec3 rgb = clamp(r.rgb, 0.0, 1.0);
    float aR;
    vec3 cor;
    if (unmult) {
        aR = min(max(rgb.r, max(rgb.g, rgb.b)), 1.0);
        cor = aR > 0.0 ? rgb / aR : vec3(0.0);
    } else {
        aR = min(r.a, 1.0);
        cor = aR > 0.0 ? rgb / aR : vec3(0.0);
    }
    if (view == 1) {
        fragColor = vec4(clamp(cor, 0.0, 1.0), aR);
        return;
    }
    vec4 base = texture(inputImg, uv);
    float aB = base.a * inputOpacity * 0.01;
    vec3 bp = base.rgb * aB;
    vec3 rp = cor * aR;
    vec3 p = rayBlend == 0 ? bp + rp - bp * rp : bp + rp;
    float alfa = aB + aR - aB * aR;
    fragColor = vec4(alfa > 0.0001 ? clamp(p / alfa, 0.0, 1.0) : vec3(0.0), clamp(alfa, 0.0, 1.0));
}
